:where([data-moru-registry]) .ui-code-block {
  min-width: 0;
  max-width: 100%;
  color: var(--ui-text);
  font-family: var(--ui-font-family);
  font-size: var(--ui-type-body-size);
  font-weight: var(--ui-type-body-weight);
  line-height: var(--ui-type-body-line-height);
  letter-spacing: var(--ui-type-body-letter-spacing);
}
:where([data-moru-registry]) .ui-code-block-language {
  font-size: var(--ui-type-caption-size);
  font-weight: var(--ui-type-caption-weight);
  line-height: var(--ui-type-caption-line-height);
  letter-spacing: var(--ui-type-caption-letter-spacing);
  color: var(--ui-muted);
  overflow-wrap: anywhere;
}
:where([data-moru-registry]) .ui-code-block-title {
  font-size: var(--ui-type-label-size);
  font-weight: var(--ui-type-label-weight);
  line-height: var(--ui-type-label-line-height);
  letter-spacing: var(--ui-type-label-letter-spacing);
  overflow-wrap: anywhere;
}
:where([data-moru-registry]) .ui-code-block {
  --ui-code-block-inset: calc(var(--ui-space) * 4);
  position: relative;
  overflow: hidden;
  width: 100%;
  border: var(--ui-border-width) solid var(--ui-border);
  border-radius: calc(var(--ui-radius) + 4px);
  background: var(--ui-surface);
}
:where([data-moru-registry]) .ui-code-block-header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--ui-control-gap);
  min-width: 0;
  padding: calc(var(--ui-code-block-inset) * 0.75) var(--ui-code-block-inset);
  border-bottom: var(--ui-border-width) solid var(--ui-border);
  background: var(--ui-surface);
}
:where([data-moru-registry]) .ui-code-block-title {
  min-width: 0;
}
:where([data-moru-registry]) .ui-code-block-actions {
  margin-inline-start: auto;
  display: flex;
  gap: var(--ui-space);
}
:where([data-moru-registry]) .ui-code-block-actions .ui-button {
  padding-inline: var(--ui-space);
  min-width: var(--ui-resolved-control-height, var(--ui-control-height-sm));
}
:where([data-moru-registry]) .ui-code-block-pre {
  margin: 0;
  padding: var(--ui-code-block-inset) 0;
  overflow: auto;
  max-width: 100%;
  max-height: 420px;
  font-family: ui-monospace, SFMono-Regular, Consolas, monospace;
  font-size: var(--ui-type-caption-size);
  font-weight: 400;
  line-height: 1.65;
  letter-spacing: 0;
  tab-size: 2;
}
:where([data-moru-registry]) .ui-code-block[data-size='sm'] {
  --ui-code-block-inset: calc(var(--ui-space) * 2);
}
:where([data-moru-registry]) .ui-code-block[data-size='lg'] {
  --ui-code-block-inset: calc(var(--ui-space) * 5);
}
:where([data-moru-registry]) .ui-code-block-line {
  display: flex;
  min-width: max-content;
  min-height: 1.65em;
  padding-inline: var(--ui-code-block-inset);
}
:where([data-moru-registry]) .ui-code-block-line > span:last-of-type {
  min-width: 0;
}
:where([data-moru-registry]) .ui-code-block-number {
  display: inline-block;
  flex: 0 0 3ch;
  margin-inline-end: 2ch;
  color: var(--ui-muted);
  user-select: none;
  text-align: right;
}
:where([data-moru-registry]) .ui-code-block-pre[data-wrap='true'] {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
:where([data-moru-registry]) .ui-code-block-pre[data-wrap='true'] .ui-code-block-line {
  min-width: 0;
}
:where([data-moru-registry]) .ui-code-block-line[data-highlighted] {
  background: var(--ui-accent-soft, var(--ui-primary-soft));
  box-shadow: inset 2px 0 var(--ui-accent, var(--ui-primary));
}
:where([data-moru-registry]) .ui-code-block-pre:focus-visible {
  outline: 2px solid var(--ui-focus-ring);
  outline-offset: -2px;
}

'use client'
// Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT
import { useI18n } from './_lib/i18n'
import { forwardRef, useEffect, useId, useRef, useState, type HTMLAttributes } from 'react'
import { Check, Copy, WrapText } from 'lucide-react'
import { cn } from './_lib/cn'
import { Button } from './button'
import './content-shared.css'
import './code-block.css'

export interface CodeBlockProps extends Omit<
  HTMLAttributes<HTMLDivElement>,
  'children' | 'onCopy'
> {
  value: string
  language?: string
  filename?: string
  lineNumbers?: boolean
  defaultWrap?: boolean
  copyable?: boolean
  disabled?: boolean
  highlightLines?: number[]
  onCopy?: () => void
  onCopyError?: (error: unknown) => void
  size?: 'sm' | 'md' | 'lg'
}
export const CodeBlock = forwardRef<HTMLDivElement, CodeBlockProps>(function CodeBlock(
  {
    value,
    language = 'text',
    filename,
    lineNumbers = false,
    defaultWrap = false,
    copyable = true,
    disabled,
    highlightLines = [],
    onCopy,
    onCopyError,
    size = 'md',
    className,
    ...props
  },
  ref,
) {
  const { t } = useI18n()

  const [copied, setCopied] = useState(false)
  const [copyError, setCopyError] = useState(false)
  const [wrap, setWrap] = useState(defaultWrap)
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null)
  const mounted = useRef(true)
  const id = useId()
  useEffect(() => {
    mounted.current = true
    return () => {
      mounted.current = false
      if (timer.current) clearTimeout(timer.current)
    }
  }, [])
  async function copy() {
    if (disabled) return
    try {
      if (!navigator.clipboard?.writeText) throw new Error('Clipboard unavailable')
      await navigator.clipboard.writeText(value)
      if (!mounted.current) return
      setCopied(true)
      setCopyError(false)
      onCopy?.()
      if (timer.current) clearTimeout(timer.current)
      timer.current = setTimeout(() => setCopied(false), 2000)
    } catch (error) {
      if (mounted.current) {
        setCopyError(true)
        setCopied(false)
        onCopyError?.(error)
      }
    }
  }
  const lines = value.split('\n')
  return (
    <div {...props} ref={ref} className={cn('ui-code-block', className)} data-size={size}>
      <div className="ui-code-block-header">
        <span id={`${id}-title`} className="ui-code-block-title">
          {filename ?? language}
        </span>
        {filename && <span className="ui-code-block-language">{language}</span>}
        <div className="ui-code-block-actions">
          <Button
            variant="ghost"
            size="sm"
            aria-label={t('코드 줄바꿈')}
            aria-pressed={wrap}
            disabled={disabled}
            onClick={() => setWrap(!wrap)}
          >
            <WrapText size={14} aria-hidden="true" />
          </Button>
          {copyable && (
            <Button
              variant="ghost"
              size="sm"
              aria-label={copied ? t('코드 복사 완료') : t('코드 복사')}
              disabled={disabled}
              onClick={copy}
            >
              {copied ? (
                <Check size={14} aria-hidden="true" />
              ) : (
                <Copy size={14} aria-hidden="true" />
              )}
            </Button>
          )}
        </div>
      </div>
      <pre
        tabIndex={0}
        role="region"
        aria-labelledby={`${id}-title`}
        className="ui-code-block-pre"
        dir="ltr"
        data-wrap={wrap}
        data-line-numbers={lineNumbers}
      >
        <code>
          {lines.map((line, index) => (
            <span
              key={index}
              className="ui-code-block-line"
              data-highlighted={highlightLines.includes(index + 1) || undefined}
            >
              {lineNumbers && (
                <span className="ui-code-block-number" aria-hidden="true">
                  {index + 1}
                </span>
              )}
              <span>{line}</span>
            </span>
          ))}
        </code>
      </pre>
      <span className="ui-content-sr-only" role="status">
        {copied
          ? t('코드를 복사했어요.')
          : copyError
            ? t('복사하지 못했어요. 코드를 선택해서 복사해 주세요.')
            : ''}
      </span>
    </div>
  )
})
